const results = $input.first().json.results || [];
if (results.length === 0) {
  return [];
}

return results.map(item => ({
  json: {
    page_id: item.id,
    title: (item.properties['Task Name']?.title || []).map(t => t.plain_text).join('') || 'Untitled',
    priority: item.properties['Priority']?.select?.name || 'P3 - Medium',
    complexity: item.properties['Complexity']?.select?.name || '⭐ 3',
    endDate: item.properties['End Date']?.date?.start || 'Past'
  }
}));

const rolledOver = $input.all();
const count = rolledOver.length;

const widgets = [
  {
    textParagraph: {
      text: `<b>Sprint Cutoff Reached:</b> <b>${count} tasks</b> missed their End Date cutoff and have been automatically rolled over into <b>Backlog Debt</b> for sprint triage.`
    }
  }
];

for (const item of rolledOver.slice(0, 5)) {
  widgets.push({
    decoratedText: {
      topLabel: `Rolled-Over Debt | End Date: ${item.json.endDate}`,
      text: `• <b>${item.json.title}</b> (${item.json.priority} | ${item.json.complexity})`
    }
  });
}

widgets.push({
  buttonList: {
    buttons: [
      {
        text: 'OPEN WASP DASHBOARD',
        onClick: {
          openLink: {
            url: 'https://app.notion.com/p/WASP-Dashboard-Work-Analysis-System-Profile-Dashboard-3fff1bcff9b88188b004f044be8090fe'
          }
        }
      }
    ]
  }
});

const googleChatPayload = {
  cardsV2: [
    {
      cardId: 'wasp_sprint_rollover_' + Date.now(),
      card: {
        header: {
          title: '🐝 WASP Engine — Sprint Backlog Rollover',
          subtitle: `${count} Incomplete Tasks Converted to Backlog Debt`,
          imageUrl: 'https://cdn-icons-png.flaticon.com/512/3281/3281307.png',
          imageType: 'CIRCLE'
        },
        sections: [
          {
            header: 'Rolled-Over Backlog Debt Summary',
            widgets: widgets
          }
        ]
      }
    }
  ]
};

return [{
  json: {
    count,
    googleChatPayload
  }
}];
